code.java:
import java.util.*;

public class Main {
    static long total(long n) {
        if (n == 0) {
            return 0;
        }
        return n + total(n - 1);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();

        System.out.println(total(n));
    }
}
